mcpToolList.inputSchema:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "query": {
      "type": "string",
      "title": "查询文本",
      "description": "待检索的问题或关键词，不能为空。自研库、三方库均支持。"
    },
    "searchStrategy": {
      "type": "string",
      "title": "检索策略",
      "enum": ["SEMANTIC", "KEYWORD", "HYBRID"],
      "default": "HYBRID",
      "description": "指定语义检索、关键词检索或混合检索。SEMANTIC（语义）、KEYWORD（关键词）、HYBRID（混合）。自研库、三方库均支持。默认值：HYBRID（混合检索）。"
    },
    "semanticTopK": {
      "type": "integer",
      "title": "语义候选数",
      "minimum": 1,
      "default": 20,
      "description": "语义检索的候选数量。仅三方库支持；在 SEMANTIC/HYBRID 策略下作为 denseSimilarityTopK，自研库不生效。默认值：20。"
    },
    "keywordTopK": {
      "type": "integer",
      "title": "关键词候选数",
      "minimum": 1,
      "default": 20,
      "description": "关键词检索的候选数量。仅三方库支持；在 KEYWORD/HYBRID 策略下作为 sparseSimilarityTopK，自研库不生效。默认值：20。"
    },
    "topK": {
      "type": "integer",
      "title": "最终返回数",
      "minimum": 1,
      "default": 10,
      "description": "最终返回的候选数量。自研库、三方库均支持。默认值：10。"
    },
    "baseIds": {
      "type": "array",
      "title": "知识库 ID 列表",
      "items": { "type": "integer" },
      "description": "限定检索范围的知识库 ID 列表。自研库、三方库均支持；与 baseNames 至少传一个，同时传入时按交集筛选。"
    },
    "baseNames": {
      "type": "array",
      "title": "知识库名称列表",
      "items": { "type": "string" },
      "description": "限定检索范围的知识库名称列表。自研库、三方库均支持；与 baseIds 至少传一个，同时传入时按交集筛选。"
    },
    "questionOptimize": {
      "type": "boolean",
      "title": "问题优化",
      "default": true,
      "description": "是否启用问题优化。自研库、三方库均支持。默认值：true（启用）。"
    },
    "rerank": {
      "type": "boolean",
      "title": "重排序开关",
      "default": true,
      "description": "是否启用重排序。自研库、三方库均支持。默认值：true（启用）。"
    },
    "score": {
      "type": "number",
      "title": "重排序分数阈值",
      "default": 0.40,
      "description": "重排序的最低分数阈值。自研库、三方库均支持。默认值：0.40。"
    },
    "history": {
      "type": "array",
      "title": "历史对话记录",
      "items": { "type": "object" },
      "default": [],
      "description": "用于传入历史对话记录。自研库、三方库均不支持；当前不会写入下游 RagDto.history 或三方请求，传入不生效。默认值：[]（空数组）。"
    }
  },
  "required": ["query", "searchStrategy"]
}

